55	// =============================================
56	// JOB
57	// =============================================
58	
59	export interface Job {
60	  id: string;
61	  display_code?: string;
62	  title: string;
63	  description?: string;
64	  briefing?: string;
65	  type?: string;
66	  status: string;
67	  location: string;
68	  start_date: string;
