86	
87	// =============================================
88	// APPLICATION
89	// =============================================
90	
91	/**
92	 * Status de application (pull = candidatura worker; push = convite empresa).
93	 * 'invited'  — empresa convidou; aguarda resposta do freela (R5/R7).
94	 * 'declined' — freela recusou; NEUTRO, zero punição (R7).
95	 * Demais status: fluxo pull legado.
96	 */
97	export type ApplicationStatus =
98	  | 'pending'
99	  | 'reviewing'
100	  | 'interview'
101	  | 'hired'
102	  | 'in_progress'
103	  | 'completed'
104	  | 'rejected'
105	  | 'invited'
106	  | 'declined';
107	
108	/**
109	 * Resposta do freela a um convite push.
110	 * NULL enquanto o convite está pendente.
111	 */
112	export type InvitationResponse = 'accepted' | 'declined';
113	
114	export interface Application {
115	  id: string;
116	  job_id: string;
117	  worker_id: string;
118	  /** Usa ApplicationStatus — restrinja ao tipo ao criar/actualizar. */
119	  status: ApplicationStatus | string;
120	  cover_letter?: string;
121	  created_at?: string;
122	  worker_checkin_at?: string | null;
123	  worker_checkout_at?: string | null;
124	  company_checkin_confirmed_at?: string | null;
125	  company_checkout_confirmed_at?: string | null;
126	  // --- campos de convite push (nullable — null = fluxo pull) ---
127	  /** Quando a empresa criou o convite. NULL = aplicação pull. */
128	  invited_by_company_at?: string | null;
129	  /** Quando o freela respondeu ao convite. */
130	  invitation_responded_at?: string | null;
131	  /** Resposta do freela: 'accepted' | 'declined' | null (pendente). */
132	  invitation_response?: InvitationResponse | null;
133	  /** Data-limite para o freela responder (R8). Após esta data, slot reabre. */
134	  invitation_expires_at?: string | null;
135	  worker?: Partial<WorkerProfile>;
136	  job?: Partial<Job>;
137	}
138	
139	// =============================================
140	// TEAM CONNECTIONS
141	// =============================================
142	
143	/**
144	 * Status da aresta consentida empresa↔freela (R1/R2).
145	 * 'pending'  — empresa convidou, aguarda aceite do freela.
146	 * 'accepted' — freela aceitou; handshake concluído (1x).
147	 * 'blocked'  — freela saiu/bloqueou a empresa.
148	 */
149	export type TeamConnectionStatus = 'pending' | 'accepted' | 'blocked';
150	
151	/**
152	 * Canal pelo qual a empresa adicionou o freela ao roster.
153	 */
154	export type TeamConnectionSource = 'qr' | 'link' | 'phone';
155	
156	/**
157	 * Espelha a tabela `team_connections`.
158	 * Gerado à mão conforme migration `20260622000000_team_connections.sql`.
159	 */
160	export interface TeamConnection {
161	  id: string;
162	  company_id: string;
163	  worker_id: string;
164	  status: TeamConnectionStatus;
165	  source: TeamConnectionSource;
166	  /** auth.uid() de quem bloqueou (auditoria). */
167	  blocked_by?: string | null;
168	  created_at: string;
169	  accepted_at?: string | null;
170	  updated_at: string;
171	  // --- joins opcionais para UI ---
172	  worker?: Partial<WorkerProfile>;
173	  company?: Partial<CompanyProfile>;
174	}
175	
176	/**
177	 * Membro da equipe: conexão aceita com perfil do worker embutido.
178	 * Retornado por TeamConnectionService.listTeamMembers().
179	 */
180	export interface TeamMember {
181	  connection: TeamConnection;
182	  worker: WorkerProfile;
183	}
184	
185	/**
186	 * "Minha loja": conexão aceita vista pelo worker, com dados da empresa.
187	 * Retornado por TeamConnectionService.listMyStores().
188	 */
189	export interface MyStore {
190	  connection: TeamConnection;
191	  company: CompanyProfile;
192	}
193	
194	// =============================================
195	// PAGAMENTO POSTPAGO (Slice 2) — cartão on-file da empresa
196	// =============================================
197	
198	/**
199	 * Método de pagamento on-file da empresa (cartão tokenizado no Asaas).
200	 * Espelha public.payment_methods (migration 20260622000600). NUNCA carrega o PAN —
201	 * só o token opaco do Asaas + metadados não-sensíveis (PCI / Article 10).
202	 */
203	export interface PaymentMethod {
204	  id: string;
205	  /** company_id = auth.uid() da empresa (= jobs.company_id = wallets.user_id). */
206	  company_id: string;
207	  /** creditCardToken opaco do Asaas (não é o número do cartão). */
208	  asaas_credit_card_token: string;
209	  brand?: string | null;
210	  /** 4 dígitos finais para exibição ("•••• 1234"). */
211	  last4?: string | null;
212	  holder_name?: string | null;
213	  is_default: boolean;
214	  created_at: string;
215	  updated_at: string;
216	}
217	
218	/** prepaid = fluxo pull legado (saldo pré-depositado); postpaid = push Slice 2 (hold no cartão). */
219	export type EscrowKind = 'prepaid' | 'postpaid';
220	
221	/**
222	 * Estados do escrow. Prepago: reserved→released|refunded. Postpago: authorized→captured→released,
223	 * ou authorized→refunded (cancel/no-show). Espelha o CHECK de escrow_transactions.status
224	 * (migration 20260622000700).
225	 */
226	export type EscrowStatus = 'reserved' | 'authorized' | 'captured' | 'released' | 'refunded';
227	
228	// =============================================
229	// MESSAGING
230	// =============================================
231	
232	export interface Message {
233	  id: string;
234	  content: string;
235	  senderid: string;
236	  createdat: string;
237	  conversationid?: string;
238	  read_at?: string | null;
239	  is_mine?: boolean;
240	}
241	
242	export interface ConversationItem {
243	  id: string;
244	  application_uuid: string;
245	  job_title: string;
246	  last_message?: string;
247	  last_message_at?: string;
248	  unread_count: number;
249	  status: string;
250	}
251	
252	export interface WorkerConversationItem extends ConversationItem {
253	  company_name: string;
254	  company_logo?: string;
255	}
256	
257	export interface CompanyConversationItem extends ConversationItem {
258	  worker_name: string;
259	  worker_avatar?: string;
260	}
261	
262	// =============================================
263	// REVIEW
264	// =============================================
265	
266	/**
267	 * Direção da avaliação (coluna adicionada em `20260622000200_company_rating_trigger.sql`).
268	 * 'worker'  → empresa avaliou o freela (reviewed_id é worker).
269	 * 'company' → freela avaliou a empresa (reviewed_id é company).
270	 * NULL = legado (pre-migration).
271	 * IMPORTANTE: reviewer_id/reviewed_id são TEXT no DB (não UUID).
272	 */
273	export type ReviewDirection = 'worker' | 'company';
274	
275	export interface Review {
276	  id: string;
277	  rating: number;
278	  comment?: string;
279	  /** TEXT no DB — não cast para UUID. */
280	  reviewer_id: string;
281	  /** TEXT no DB — não cast para UUID. */
282	  reviewed_id?: string;
283	  /** @deprecated use reviewed_id */
284	  reviewee_id?: string;
285	  application_id?: string;
286	  /**
287	   * Direção explícita: quem é o avaliado.
288	   * Passar SEMPRE ao inserir: 'worker' quando empresa avalia freela;
289	   * 'company' quando freela avalia empresa.
290	   * O trigger BEFORE INSERT (`set_review_direction`) preenche automaticamente
291	   * se omitido, mas o service DEVE passar explicitamente (ADR-001).
292	   */
293	  direction?: ReviewDirection | null;
294	  created_at?: string;
295	  company?: { name: string };
296	}
297	
298	// =============================================
299	// NOTIFICATION
300	// =============================================
301	
302	export interface Notification {
303	  id: string;
304	  user_id?: string;
305	  type: 'status_change' | 'message' | 'payment' | 'system';
306	  title: string;
307	  message: string;
308	  link?: string;
309	  read_at: string | null;
310	  created_at: string;
311	}
