142	/** Obtém o company_id da sessão autenticada (empresa). */
143	async function getAuthCompanyId(): Promise<string> {
144	  const {
145	    data: { user },
146	  } = await supabase.auth.getUser();
147	  if (!user) throw new Error('Sessão expirada. Faça login novamente.');
148	
149	  const { data: company, error } = await supabase
150	    .from('companies')
151	    .select('id')
152	    .eq('owner_id', user.id)
153	    .maybeSingle();
154	
155	  if (error) throw error;
156	  if (!company) throw new Error('Perfil de empresa não encontrado.');
157	
158	  return company.id as string;
159	}
