172	export const ShiftInviteService = {
173	  // -------------------------------------------------------------------------
174	  // EMPRESA: convidar worker para turno
175	  // -------------------------------------------------------------------------
176	
177	  /**
178	   * Convida um worker da equipe para um turno específico.
179	   *
180	   * Pré-condições verificadas:
181	   *  1. O worker é conexão 'accepted' da empresa (R2 — lista fechada).
182	   *  2. Não existe convite ativo (invited) para o mesmo job+worker.
183	   *
184	   * Ações:
185	   *  1. Insere em `applications` com status='invited'.
186	   *  2. Cria notificação in-app (insert em `notifications`).
187	   *  3. Invoca `send-notification` para entrega por e-mail.
188	   *
189	   * Não chama reserve_escrow (Slice 2).
190	   *
191	   * @param jobId    UUID do turno (job).
192	   * @param workerId UUID do worker a convidar.
193	   * @param opts     Opções adicionais.
194	   */
195	  async inviteWorkerToShift(
196	    jobId: string,
197	    workerId: string,
198	    opts: InviteWorkerToShiftOptions = {},
199	  ): Promise<InviteWorkerResult> {
200	    try {
201	      const companyId = await getAuthCompanyId();
202	
203	      // 1. Validar que o worker está na equipe aceita (R2)
204	      const inTeam = await TeamConnectionService.isWorkerInTeam(companyId, workerId);
205	      if (!inTeam) {
206	        return {
207	          application: null,
208	          error:
209	            'O freela não está na sua equipe. Adicione-o primeiro para poder convidar.',
210	        };
211	      }
212	
213	      // 2. Verificar se já existe convite pendente (idempotência)
214	      const { data: existing, error: checkErr } = await supabase
215	        .from('applications')
216	        .select('id, status')
217	        .eq('job_id', jobId)
218	        .eq('worker_id', workerId)
219	        .maybeSingle();
220	
221	      if (checkErr) {
222	        logError('shiftInvite.inviteWorkerToShift.check', checkErr);
223	        return { application: null, error: 'Erro ao verificar convite existente.' };
224	      }
225	
226	      if (existing) {
227	        // Já existe application (qualquer status)
228	        if (existing.status === 'invited') {
229	          return {
230	            application: existing as Application,
231	            alreadyInvited: true,
232	          };
233	        }
234	        return {
235	          application: null,
236	          error: `Já existe uma candidatura para este turno com status '${existing.status}'.`,
237	        };
238	      }
239	
240	      // 3. Calcular expiração
241	      const expiresInHours = opts.expiresInHours ?? DEFAULT_INVITE_EXPIRY_HOURS;
242	      const expiresAt = calcExpiry(expiresInHours);
243	      const now = new Date().toISOString();
244	
245	      // 4. Inserir convite em applications
246	      const { data: application, error: insertErr } = await supabase
247	        .from('applications')
248	        .insert({
249	          job_id: jobId,
250	          worker_id: workerId,
251	          status: 'invited' as ApplicationStatus,
252	          invited_by_company_at: now,
253	          invitation_expires_at: expiresAt,
254	        })
255	        .select()
256	        .single();
257	
258	      if (insertErr) {
259	        if (insertErr.code === '23505') {
260	          return { application: null, alreadyInvited: true };
261	        }
262	        logError('shiftInvite.inviteWorkerToShift.insert', insertErr);
263	        return { application: null, error: 'Não foi possível criar o convite.' };
264	      }
265	
266	      // 5. Notificação in-app (insert direto em notifications)
267	      const { error: notifErr } = await supabase.from('notifications').insert({
268	        user_id: workerId,
269	        type: 'status_change',
270	        title: 'Novo convite de turno',
271	        message:
272	          opts.message ??
273	          'Você recebeu um convite para um turno. Acesse "Convites" para aceitar ou recusar.',
274	        link: `/my-jobs`,
275	      });
276	
277	      if (notifErr) {
278	        // Não bloqueia — a application foi criada; notificação é best-effort
279	        logError('shiftInvite.inviteWorkerToShift.notif', notifErr);
280	      }
281	
282	      // 6. Entrega por e-mail via send-notification (best-effort)
283	      try {
284	        await invokeFunction('send-notification', {
285	          userId: workerId,
286	          type: 'shift_invite',
287	          data: {
288	            jobId,
289	            applicationId: application.id,
290	            expiresAt,
291	          },
292	        });
293	      } catch (emailErr) {
294	        // Edge function falhou — não bloqueia o convite
295	        logError('shiftInvite.inviteWorkerToShift.email', emailErr);
296	      }
297	
298	      return { application: application as Application };
299	    } catch (err) {
300	      logError('shiftInvite.inviteWorkerToShift', err);
301	      return {
302	        application: null,
303	        error: err instanceof Error ? err.message : 'Erro inesperado.',
304	      };
305	    }
306	  },
307	
308	  // -------------------------------------------------------------------------
309	  // WORKER: responder ao convite (aceitar ou recusar)
310	  // -------------------------------------------------------------------------
311	
312	  /**
313	   * Worker responde a um convite de turno.
314	   *
315	   * Máquina de estados (validada aqui — ADR-001):
316	   *   'invited' → 'hired'    (quando accepted)
317	   *   'invited' → 'declined' (quando declined — NEUTRO, zero punição — R7)
318	   *
319	   * NÃO chama reserve_escrow (postpago é Slice 2; Slice 2 adiciona o hook aqui).
320	   *
321	   * @param applicationId UUID da application (convite).
322	   * @param response      'accepted' | 'declined'.
323	   */
324	  async respondToInvite(
325	    applicationId: string,
326	    response: InvitationResponse,
327	  ): Promise<RespondToInviteResult> {
328	    try {
329	      const {
330	        data: { user },
331	      } = await supabase.auth.getUser();
332	      if (!user) return { success: false, error: 'Sessão expirada.' };
333	
334	      // 1. Buscar application atual (validar máquina de estados)
335	      const { data: current, error: fetchErr } = await supabase
336	        .from('applications')
337	        .select('id, status, worker_id, job_id, invited_by_company_at, invitation_expires_at')
338	        .eq('id', applicationId)
339	        .maybeSingle();
340	
341	      if (fetchErr) {
342	        logError('shiftInvite.respondToInvite.fetch', fetchErr);
343	        return { success: false, error: 'Convite não encontrado.' };
344	      }
345	      if (!current) return { success: false, error: 'Convite não encontrado.' };
346	      if (current.worker_id !== user.id) {
347	        return { success: false, error: 'Este convite não é para você.' };
348	      }
349	      if (current.status !== 'invited') {
350	        return {
351	          success: false,
352	          error: `Transição inválida: status atual é '${current.status}', esperado 'invited'.`,
353	        };
354	      }
355	
356	      // 2. Verificar expiração (R8)
357	      if (current.invitation_expires_at) {
358	        const expiresAt = new Date(current.invitation_expires_at as string);
359	        if (expiresAt < new Date()) {
360	          return {
361	            success: false,
362	            error: 'Este convite expirou. O operador precisará reenviar um novo convite.',
363	          };
364	        }
365	      }
366	
367	      // 3. Mapear response → status final
368	      //    accepted → 'hired' (turno confirmado para os dois lados — sem escrow neste slice)
369	      //    declined → 'declined' (neutro — R7)
370	      const newStatus: ApplicationStatus = response === 'accepted' ? 'hired' : 'declined';
371	      const now = new Date().toISOString();
372	
373	      const { error: updateErr } = await supabase
374	        .from('applications')
375	        .update({
376	          status: newStatus,
377	          invitation_response: response,
378	          invitation_responded_at: now,
379	        })
380	        .eq('id', applicationId)
381	        .eq('worker_id', user.id);
382	
383	      if (updateErr) {
384	        logError('shiftInvite.respondToInvite.update', updateErr);
385	        return { success: false, error: 'Erro ao registrar resposta.' };
386	      }
387	
388	      // 4. Resolver o owner da empresa (necessário tanto para notificação de aceite quanto
389	      //    para notificação de falha de cartão em dispatchAuthorizePayment).
390	      let companyOwnerId: string | null = null;
391	      if (response === 'accepted') {
392	        const { data: jobRow } = await supabase
393	          .from('applications')
394	          .select('job:jobs(company_id)')
395	          .eq('id', applicationId)
396	          .maybeSingle();
397	
398	        const companyId = (jobRow?.job as { company_id?: string } | null)?.company_id;
399	        if (companyId) {
400	          const { data: companyRow } = await supabase
401	            .from('companies')
402	            .select('owner_id')
403	            .eq('id', companyId)
404	            .maybeSingle();
405	          companyOwnerId = companyRow?.owner_id ?? null;
406	        }
407	      }
408	
409	      // 5. Pré-autorização postpago (best-effort — não bloqueia o aceite em caso de falha).
410	      //    Modo 'authorize': cria hold no cartão da empresa. Modo 'charge_on_demand': no-op aqui.
411	      //    A captura (ou cobrança direta) ocorre na conclusão via asaas-capture-payment.
412	      //    Em card_declined, dispatchAuthorizePayment já envia notificação à empresa.
413	      if (response === 'accepted') {
414	        await dispatchAuthorizePayment(current.job_id, applicationId, companyOwnerId ?? '');
415	      }
416	
417	      // 6. Notificação in-app para a empresa sobre o aceite (best-effort)
418	      if (response === 'accepted' && companyOwnerId) {
419	        const { error: notifErr } = await supabase.from('notifications').insert({
420	          user_id: companyOwnerId,
421	          type: 'status_change',
422	          title: 'Freela aceitou o turno',
423	          message: 'Um freela aceitou seu convite de turno.',
424	          link: `/company/jobs/${current.job_id}/candidates`,
425	        });
426	
427	        if (notifErr) {
428	          logError('shiftInvite.respondToInvite.notif', notifErr);
429	        }
430	      }
431	
432	      return { success: true };
433	    } catch (err) {
434	      logError('shiftInvite.respondToInvite', err);
435	      return {
436	        success: false,
437	        error: err instanceof Error ? err.message : 'Erro inesperado.',
438	      };
439	    }
440	  },
