/**
 * SpendLimitService — teto de gasto + alertas in-app (Slice 3, R12).
 *
 * Responsabilidades:
 *  1. CRUD do teto de gasto (company_spend_limits).
 *  2. CRUD do faturamento mensal declarado (company_monthly_revenue).
 *  3. evaluateSpendAlert — computa BI-1, compara com o teto, e insere alerta idempotente
 *     em `notifications` para o maior threshold cruzado ainda não alertado.
 *
 * Contratos do architect (spec Slice 3):
 *  - Gasto = escrow_transactions WHERE status IN ('released','captured').
 *  - Período: COALESCE(captured_at, released_at, created_at).
 *  - Empresa da linha: company_wallet_id → wallets.user_id = companyId.
 *  - Alerta NUNCA bloqueia contratação.
 *  - Idempotência via link='/company/financeiro?alert=<companyId>:<YYYYMM>:<threshold>'
 *    + SELECT LIMIT 1 antes do INSERT.
 *  - Dispara APENAS o maior threshold cruzado ainda não alertado no período.
 *  - Threshold >100% usa chave ':OVER'.
 *
 * Padrões do projeto:
 *  - Fetch: supabase.from direto (Art. 5 — sem React Query).
 *  - Tipos à mão em types/index.ts (Art. 2).
 *  - Imports relativos (sem alias @/).
 *  - logError (nunca console.log).
 */

import { supabase } from '../lib/supabase';
import { logError } from '../lib/logger';
import type { SpendLimit, MonthlyRevenue } from '../types';

// ---------------------------------------------------------------------------
// Helpers de período
// ---------------------------------------------------------------------------

/** Retorna o primeiro dia do mês de uma Date no formato ISO date (YYYY-MM-DD). */
function monthStart(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-01`;
}

/** Retorna o primeiro dia do MÊS SEGUINTE de uma Date no formato ISO date. */
function nextMonthStart(d: Date): string {
  const next = new Date(d.getFullYear(), d.getMonth() + 1, 1);
  return `${next.getFullYear()}-${String(next.getMonth() + 1).padStart(2, '0')}-01`;
}

/** Formata YYYYMM a partir de uma Date (para a chave de idempotência de alerta). */
function yyyymm(d: Date): string {
  return `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}`;
}

// ---------------------------------------------------------------------------
// Helpers de query
// ---------------------------------------------------------------------------

/**
 * Calcula o gasto acumulado de uma empresa no mês corrente (BI-1).
 * Gasto = SUM(amount) de escrow_transactions com status IN ('released','captured')
 * filtrado pelo carimbo COALESCE(captured_at, released_at, created_at) dentro do mês.
 *
 * A empresa é identificada via company_wallet_id → wallets.user_id = companyId.
 *
 * @returns { totalAmount, periodStart, periodEnd } ou null em caso de erro.
 */
async function computeAccumulatedSpend(
  companyId: string,
  now: Date,
): Promise<{ totalAmount: number; periodStart: string; periodEnd: string } | null> {
  try {
    const ps = monthStart(now);
    const pe = nextMonthStart(now);

    // Buscar o wallet_id da empresa
    const { data: wallet, error: walletErr } = await supabase
      .from('wallets')
      .select('id')
      .eq('user_id', companyId)
      .maybeSingle();

    if (walletErr) {
      logError('spendLimit.computeAccumulatedSpend.wallet', walletErr);
      return null;
    }
    if (!wallet) return { totalAmount: 0, periodStart: ps, periodEnd: pe };

    // Soma do gasto efetivo (released + captured) no período
    // Filtra pelo carimbo: COALESCE(captured_at, released_at, created_at)
    // PostgREST não suporta COALESCE em filtros → buscar as linhas e filtrar em JS.
    // Volume esperado: dezenas/centenas por empresa por mês → ok.
    const { data: rows, error: escrowErr } = await supabase
      .from('escrow_transactions')
      .select('amount, captured_at, released_at, created_at')
      .eq('company_wallet_id', wallet.id)
      .in('status', ['released', 'captured']);

    if (escrowErr) {
      logError('spendLimit.computeAccumulatedSpend.escrow', escrowErr);
      return null;
    }

    const psDate = new Date(ps);
    const peDate = new Date(pe);
    let totalAmount = 0;

    for (const row of rows ?? []) {
      const stamp = new Date(
        (row.captured_at as string | null) ??
        (row.released_at as string | null) ??
        (row.created_at as string),
      );
      if (stamp >= psDate && stamp < peDate) {
        totalAmount += Number(row.amount ?? 0);
      }
    }

    return { totalAmount, periodStart: ps, periodEnd: pe };
  } catch (err) {
    logError('spendLimit.computeAccumulatedSpend', err);
    return null;
  }
}

// ---------------------------------------------------------------------------
// SpendLimitService (exportado)
// ---------------------------------------------------------------------------

export const SpendLimitService = {
  // -------------------------------------------------------------------------
  // CRUD — teto de gasto
  // -------------------------------------------------------------------------

  /**
   * Busca o teto de gasto mensal da empresa. Retorna null se não configurado.
   * scope NULL = empresa inteira (caso v1 single-store).
   */
  async getSpendLimit(companyId: string, scope: string | null = null): Promise<SpendLimit | null> {
    try {
      let query = supabase
        .from('company_spend_limits')
        .select('*')
        .eq('company_id', companyId)
        .eq('period', 'month');

      if (scope === null) {
        query = query.is('scope', null);
      } else {
        query = query.eq('scope', scope);
      }

      const { data, error } = await query.maybeSingle();
      if (error) {
        logError('spendLimit.getSpendLimit', error);
        return null;
      }
      return (data as SpendLimit) ?? null;
    } catch (err) {
      logError('spendLimit.getSpendLimit', err);
      return null;
    }
  },

  /**
   * Cria ou atualiza o teto de gasto mensal da empresa (upsert idempotente).
   * Usa ON CONFLICT (company_id, period) WHERE scope IS NULL (índice parcial da migration).
   *
   * @returns SpendLimit atualizado ou null em caso de erro.
   */
  async upsertSpendLimit(
    companyId: string,
    params: {
      amount: number;
      alertThresholds?: number[];
      scope?: string | null;
      financialContactEmail?: string | null;
      financialContactPhone?: string | null;
    },
  ): Promise<SpendLimit | null> {
    try {
      const payload: Record<string, unknown> = {
        company_id: companyId,
        period: 'month',
        amount: params.amount,
        scope: params.scope ?? null,
      };
      if (params.alertThresholds !== undefined) {
        payload.alert_thresholds = params.alertThresholds;
      }
      if (params.financialContactEmail !== undefined) {
        payload.financial_contact_email = params.financialContactEmail;
      }
      if (params.financialContactPhone !== undefined) {
        payload.financial_contact_phone = params.financialContactPhone;
      }

      const { data, error } = await supabase
        .from('company_spend_limits')
        .upsert(payload, { onConflict: 'company_id,period,scope' })
        .select()
        .single();

      if (error) {
        logError('spendLimit.upsertSpendLimit', error);
        return null;
      }
      return data as SpendLimit;
    } catch (err) {
      logError('spendLimit.upsertSpendLimit', err);
      return null;
    }
  },

  // -------------------------------------------------------------------------
  // CRUD — faturamento mensal
  // -------------------------------------------------------------------------

  /**
   * Busca o faturamento declarado da empresa em um mês (year_month = DATE no dia 1).
   * Normaliza para o primeiro dia do mês automaticamente.
   *
   * @param yearMonth Date ou string YYYY-MM-DD (sempre normalizada para o dia 1).
   */
  async getMonthlyRevenue(
    companyId: string,
    yearMonth: Date | string,
  ): Promise<MonthlyRevenue | null> {
    try {
      const ym =
        typeof yearMonth === 'string'
          ? yearMonth.slice(0, 7) + '-01'
          : monthStart(yearMonth);

      const { data, error } = await supabase
        .from('company_monthly_revenue')
        .select('*')
        .eq('company_id', companyId)
        .eq('year_month', ym)
        .maybeSingle();

      if (error) {
        logError('spendLimit.getMonthlyRevenue', error);
        return null;
      }
      return (data as MonthlyRevenue) ?? null;
    } catch (err) {
      logError('spendLimit.getMonthlyRevenue', err);
      return null;
    }
  },

  /**
   * Cria ou atualiza o faturamento declarado do mês (upsert idempotente).
   * Normaliza year_month para o primeiro dia do mês.
   *
   * @param yearMonth Date ou string YYYY-MM-DD.
   * @param amount    Faturamento bruto BRL (>= 0).
   */
  async upsertMonthlyRevenue(
    companyId: string,
    yearMonth: Date | string,
    amount: number,
  ): Promise<MonthlyRevenue | null> {
    try {
      const ym =
        typeof yearMonth === 'string'
          ? yearMonth.slice(0, 7) + '-01'
          : monthStart(yearMonth);

      const { data, error } = await supabase
        .from('company_monthly_revenue')
        .upsert(
          { company_id: companyId, year_month: ym, amount },
          { onConflict: 'company_id,year_month' },
        )
        .select()
        .single();

      if (error) {
        logError('spendLimit.upsertMonthlyRevenue', error);
        return null;
      }
      return data as MonthlyRevenue;
    } catch (err) {
      logError('spendLimit.upsertMonthlyRevenue', err);
      return null;
    }
  },

  // -------------------------------------------------------------------------
  // Avaliação do alerta de teto (R12)
  // -------------------------------------------------------------------------

  /**
   * Avalia se o gasto acumulado do mês corrente cruzou algum threshold do teto.
   * Insere alerta idempotente em `notifications` para o MAIOR threshold cruzado
   * ainda não alertado no período.
   *
   * Regras (spec Slice 3 — contrato de ALERTA):
   *  - Dispara apenas o MAIOR threshold cruzado não-alertado (ex.: cruzou 92% → alerta 90%, não 80%).
   *  - Threshold >100% usa chave 'OVER'.
   *  - Idempotência: verifica SELECT LIMIT 1 por link antes do INSERT.
   *  - NUNCA bloqueia contratação (exceções capturadas silenciosamente — best-effort).
   *  - NÃO chama dentro de RPC de saldo (Article 8).
   *
   * @param companyId   UUID da empresa (= auth.uid() da empresa = wallets.user_id).
   * @param now         Data de referência (default: Date.now()). Injetável para testes.
   */
  async evaluateSpendAlert(companyId: string, now: Date = new Date()): Promise<void> {
    try {
      // 1. Buscar o teto configurado (scope = empresa inteira, v1)
      const limit = await SpendLimitService.getSpendLimit(companyId, null);
      if (!limit || limit.amount <= 0) return; // Sem teto configurado → nada a fazer

      // 2. Calcular gasto acumulado do período
      const spend = await computeAccumulatedSpend(companyId, now);
      if (!spend) return; // Erro de query → best-effort, não bloqueia

      const { totalAmount } = spend;
      const percent = (totalAmount / limit.amount) * 100;

      // 3. Determinar o maior threshold cruzado
      //    Inclui 'OVER' se gasto > teto (>100%)
      const thresholds = [...(limit.alert_thresholds ?? [80, 90, 100])].sort((a, b) => a - b);

      let highestCrossed: number | 'OVER' | null = null;

      if (percent > 100) {
        highestCrossed = 'OVER';
      } else {
        for (const t of thresholds) {
          if (percent >= t) {
            highestCrossed = t;
          }
        }
      }

      if (highestCrossed === null) return; // Nenhum threshold cruzado

      // 4. Construir a chave de idempotência
      const periodKey = yyyymm(now);
      const thresholdKey = highestCrossed === 'OVER' ? 'OVER' : String(highestCrossed);
      const alertLink = `/company/financeiro?alert=${companyId}:${periodKey}:${thresholdKey}`;

      // 5. Resolver o owner da empresa (user_id para a notificação)
      //    Usa o financial_contact_email se disponível, mas notificação in-app vai pro owner.
      const { data: companyRow, error: companyErr } = await supabase
        .from('companies')
        .select('owner_id')
        .eq('id', companyId)
        .maybeSingle();

      if (companyErr || !companyRow) {
        logError('spendLimit.evaluateSpendAlert.company', companyErr ?? new Error('company not found'));
        return;
      }
      const ownerId = companyRow.owner_id as string;

      // 6. Verificar idempotência: já existe alerta com este link?
      //    notifications_user_id_idx cobre user_id (sem full-scan).
      const { data: existing, error: checkErr } = await supabase
        .from('notifications')
        .select('id')
        .eq('user_id', ownerId)
        .eq('link', alertLink)
        .limit(1)
        .maybeSingle();

      if (checkErr) {
        logError('spendLimit.evaluateSpendAlert.check', checkErr);
        return;
      }
      if (existing) return; // Alerta já enviado → idempotência

      // 7. Compor mensagem do alerta
      const percentFormatted = Math.round(percent);
      const amountFormatted = totalAmount.toLocaleString('pt-BR', {
        style: 'currency',
        currency: 'BRL',
      });
      const limitFormatted = limit.amount.toLocaleString('pt-BR', {
        style: 'currency',
        currency: 'BRL',
      });

      let title: string;
      let message: string;

      if (highestCrossed === 'OVER') {
        title = 'Teto de gasto ultrapassado';
        message =
          `Gasto mensal de ${amountFormatted} ultrapassou o teto de ${limitFormatted} ` +
          `(${percentFormatted}%). As contratações continuam funcionando normalmente.`;
      } else {
        title = `Alerta: ${highestCrossed}% do teto de gasto atingido`;
        message =
          `Gasto mensal de ${amountFormatted} atingiu ${percentFormatted}% do teto de ` +
          `${limitFormatted}. As contratações continuam funcionando normalmente.`;
      }

      // 8. Inserir notificação in-app
      const { error: insertErr } = await supabase.from('notifications').insert({
        user_id: ownerId,
        type: 'payment',
        title,
        message,
        link: alertLink,
      });

      if (insertErr) {
        logError('spendLimit.evaluateSpendAlert.insert', insertErr);
        // Best-effort — não propaga o erro para não quebrar o pagamento
      }
    } catch (err) {
      // NUNCA propaga — alerta é best-effort (spec: "Alerta NUNCA bloqueia")
      logError('spendLimit.evaluateSpendAlert', err);
    }
  },
};

/**
 * FinancialBIService — inteligência financeira da empresa (Slice 3, R13-R16).
 *
 * Implementa 4 queries derivadas de BI sobre escrow_transactions + jobs + applications.
 * Nenhuma view criada (decisão do architect: views não propagam RLS com segurança — spec Slice 3).
 *
 * BI-2: Gasto e horas por freela (real: checkout-checkin; fallback: jobs.estimated_hours).
 * BI-3: Ratio custo/hora + custo-%-faturamento (oculto se mês sem faturamento informado).
 * BI-4: Custo de no-show — heurística v1, ROTULADO COMO ESTIMATIVA.
 * BI-5: Flag de concentração de horas/dias por freela (risco de vínculo trabalhista).
 *
 * Contratos de dados (spec Slice 3):
 *  - Gasto = escrow_transactions WHERE status IN ('released','captured').
 *  - Carimbo: COALESCE(captured_at, released_at, created_at) — filtrar o mês por este.
 *  - Empresa da linha: company_wallet_id → wallets.user_id = companyId.
 *  - Freela: worker_wallet_id → wallets.user_id | application_id → applications.worker_id.
 *
 * Padrões do projeto:
 *  - supabase.from direto (Art. 5 — sem React Query).
 *  - Tipos à mão em types/index.ts (Art. 2).
 *  - Imports relativos (sem alias @/).
 *  - logError (nunca console.log).
 */

import { supabase } from '../lib/supabase';
import { logError } from '../lib/logger';
import type {
  AccumulatedSpend,
  SpendByWorker,
  CostRatio,
  NoShowCost,
  ConcentrationFlag,
} from '../types';

// ---------------------------------------------------------------------------
// Constantes de produto (BI-5 — limiar de concentração)
// Calibrar aqui sem migration.
// ---------------------------------------------------------------------------

/** Horas totais no período que sinalizam risco de vínculo. */
const CONCENTRATION_HOURS_THRESHOLD = 150;

/** Dias distintos no período que, combinados com as horas, sinalizam risco de vínculo. */
const CONCENTRATION_DAYS_THRESHOLD = 20;

// ---------------------------------------------------------------------------
// Helpers de período
// ---------------------------------------------------------------------------

export interface BIPeriod {
  /** Primeiro dia do mês (inclusive), ISO date string YYYY-MM-DD. */
  start: string;
  /** Primeiro dia do mês seguinte (exclusive), ISO date string YYYY-MM-DD. */
  end: string;
}

/** Retorna o período do mês corrente. */
export function currentMonthPeriod(now: Date = new Date()): BIPeriod {
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  const start = `${y}-${m}-01`;
  const next = new Date(y, now.getMonth() + 1, 1);
  const ny = next.getFullYear();
  const nm = String(next.getMonth() + 1).padStart(2, '0');
  const end = `${ny}-${nm}-01`;
  return { start, end };
}

/** Retorna um período customizado a partir de strings ISO date. */
export function customPeriod(start: string, end: string): BIPeriod {
  return { start, end };
}

// ---------------------------------------------------------------------------
// Tipos internos de linha bruta de escrow
// ---------------------------------------------------------------------------

interface EscrowRow {
  amount: number;
  captured_at: string | null;
  released_at: string | null;
  created_at: string;
  application_id: string | null;
  worker_wallet_id: string | null;
  job_id: string | null;
}

interface ApplicationRow {
  id: string;
  worker_id: string;
  job_id: string;
  status: string;
  worker_checkin_at: string | null;
  worker_checkout_at: string | null;
  invitation_response: string | null;
  invitation_expires_at: string | null;
}

interface JobRow {
  id: string;
  start_date: string;
  estimated_hours: number | null;
}

interface WorkerProfileRow {
  id: string;
  full_name: string;
  avatar_url: string | null;
  photo_url: string | null;
}

// ---------------------------------------------------------------------------
// Helper: buscar wallet_id da empresa
// ---------------------------------------------------------------------------

async function getCompanyWalletId(companyId: string): Promise<string | null> {
  const { data, error } = await supabase
    .from('wallets')
    .select('id')
    .eq('user_id', companyId)
    .maybeSingle();
  if (error) {
    logError('financialBI.getCompanyWalletId', error);
    return null;
  }
  return (data?.id as string | null) ?? null;
}

// ---------------------------------------------------------------------------
// Helper: filtrar linha de escrow pelo período (JS-side, PostgREST não suporta COALESCE)
// ---------------------------------------------------------------------------

function isInPeriod(row: EscrowRow, startDate: Date, endDate: Date): boolean {
  const stamp = new Date(
    row.captured_at ?? row.released_at ?? row.created_at,
  );
  return stamp >= startDate && stamp < endDate;
}

// ---------------------------------------------------------------------------
// FinancialBIService (exportado)
// ---------------------------------------------------------------------------

export const FinancialBIService = {
  // -------------------------------------------------------------------------
  // BI-1: Gasto acumulado do período
  // -------------------------------------------------------------------------

  /**
   * Computa o gasto acumulado da empresa no período (BI-1).
   * Fonte: escrow_transactions WHERE status IN ('released','captured'),
   * filtrado pelo carimbo COALESCE(captured_at, released_at, created_at).
   */
  async getAccumulatedSpend(companyId: string, period: BIPeriod): Promise<AccumulatedSpend> {
    const empty: AccumulatedSpend = {
      totalAmount: 0,
      periodStart: period.start,
      periodEnd: period.end,
    };

    try {
      const walletId = await getCompanyWalletId(companyId);
      if (!walletId) return empty;

      const { data: rows, error } = await supabase
        .from('escrow_transactions')
        .select('amount, captured_at, released_at, created_at')
        .eq('company_wallet_id', walletId)
        .in('status', ['released', 'captured']);

      if (error) {
        logError('financialBI.getAccumulatedSpend', error);
        return empty;
      }

      const startDate = new Date(period.start);
      const endDate = new Date(period.end);
      let totalAmount = 0;

      for (const row of (rows ?? []) as EscrowRow[]) {
        if (isInPeriod(row, startDate, endDate)) {
          totalAmount += Number(row.amount ?? 0);
        }
      }

      return { totalAmount, periodStart: period.start, periodEnd: period.end };
    } catch (err) {
      logError('financialBI.getAccumulatedSpend', err);
      return empty;
    }
  },

  // -------------------------------------------------------------------------
  // BI-2: Gasto e horas por freela no período
  // -------------------------------------------------------------------------

  /**
   * Gasto e horas por freela no período (BI-2).
   *
   * Horas reais quando houver worker_checkout_at e worker_checkin_at em applications.
   * Fallback: jobs.estimated_hours do turno concluído.
   * hoursSource = 'real' | 'estimated' | 'mixed' (por freela no período).
   *
   * Agrupa por worker_id (via application_id → applications.worker_id).
   */
  async getSpendByWorker(companyId: string, period: BIPeriod): Promise<SpendByWorker[]> {
    try {
      const walletId = await getCompanyWalletId(companyId);
      if (!walletId) return [];

      // 1. Linhas de escrow no período (com application_id para join)
      const { data: escrowRows, error: escrowErr } = await supabase
        .from('escrow_transactions')
        .select('amount, captured_at, released_at, created_at, application_id, job_id')
        .eq('company_wallet_id', walletId)
        .in('status', ['released', 'captured'])
        .not('application_id', 'is', null);

      if (escrowErr) {
        logError('financialBI.getSpendByWorker.escrow', escrowErr);
        return [];
      }

      const startDate = new Date(period.start);
      const endDate = new Date(period.end);

      // Filtrar pelo período
      const inPeriod = ((escrowRows ?? []) as EscrowRow[]).filter((r) =>
        isInPeriod(r, startDate, endDate),
      );

      if (inPeriod.length === 0) return [];

      // 2. Buscar applications (check-in/out + worker_id) para os application_ids do período
      const appIds = [...new Set(inPeriod.map((r) => r.application_id as string))];
      const jobIds = [...new Set(inPeriod.map((r) => r.job_id).filter(Boolean) as string[])];

      const [appResult, jobResult] = await Promise.all([
        supabase
          .from('applications')
          .select('id, worker_id, job_id, worker_checkin_at, worker_checkout_at, status')
          .in('id', appIds),
        jobIds.length > 0
          ? supabase
              .from('jobs')
              .select('id, estimated_hours')
              .in('id', jobIds)
          : Promise.resolve({ data: [], error: null }),
      ]);

      if (appResult.error) {
        logError('financialBI.getSpendByWorker.apps', appResult.error);
        return [];
      }
      if (jobResult.error) {
        logError('financialBI.getSpendByWorker.jobs', jobResult.error);
      }

      const appMap = new Map<string, ApplicationRow>(
        ((appResult.data ?? []) as ApplicationRow[]).map((a) => [a.id, a]),
      );
      const jobMap = new Map<string, JobRow>(
        ((jobResult.data ?? []) as JobRow[]).map((j) => [j.id, j]),
      );

      // Coletar worker_ids únicos
      const workerIds = [...new Set(
        appIds
          .map((aid) => appMap.get(aid)?.worker_id)
          .filter(Boolean) as string[],
      )];

      if (workerIds.length === 0) return [];

      // 3. Buscar perfis dos workers
      const { data: workers, error: workerErr } = await supabase
        .from('workers')
        .select('id, full_name, avatar_url, photo_url')
        .in('id', workerIds);

      if (workerErr) {
        logError('financialBI.getSpendByWorker.workers', workerErr);
      }

      const workerMap = new Map<string, WorkerProfileRow>(
        ((workers ?? []) as WorkerProfileRow[]).map((w) => [w.id, w]),
      );

      // 4. Agregar por worker
      interface WorkerAgg {
        totalAmount: number;
        totalHours: number;
        realHoursCount: number;
        estimatedHoursCount: number;
        shiftsCount: number;
      }

      const agg = new Map<string, WorkerAgg>();

      for (const row of inPeriod) {
        const app = appMap.get(row.application_id as string);
        if (!app) continue;

        const workerId = app.worker_id;
        if (!agg.has(workerId)) {
          agg.set(workerId, {
            totalAmount: 0,
            totalHours: 0,
            realHoursCount: 0,
            estimatedHoursCount: 0,
            shiftsCount: 0,
          });
        }
        const entry = agg.get(workerId)!;
        entry.totalAmount += Number(row.amount ?? 0);
        entry.shiftsCount += 1;

        // Horas: real se houver check-in/out; fallback estimated_hours
        if (app.worker_checkin_at && app.worker_checkout_at) {
          const hours =
            (new Date(app.worker_checkout_at).getTime() -
              new Date(app.worker_checkin_at).getTime()) /
            3_600_000;
          entry.totalHours += hours;
          entry.realHoursCount += 1;
        } else {
          const job = row.job_id ? jobMap.get(row.job_id) : undefined;
          const estimated = job?.estimated_hours ?? 0;
          entry.totalHours += estimated;
          entry.estimatedHoursCount += 1;
        }
      }

      // 5. Montar resultado
      const result: SpendByWorker[] = [];
      for (const [workerId, data] of agg.entries()) {
        const worker = workerMap.get(workerId);
        let hoursSource: SpendByWorker['hoursSource'] = 'estimated';
        if (data.realHoursCount > 0 && data.estimatedHoursCount === 0) {
          hoursSource = 'real';
        } else if (data.realHoursCount > 0 && data.estimatedHoursCount > 0) {
          hoursSource = 'mixed';
        }

        result.push({
          workerId,
          workerName: worker?.full_name ?? 'Worker',
          workerAvatarUrl: worker?.avatar_url ?? worker?.photo_url ?? null,
          totalAmount: data.totalAmount,
          totalHours: data.totalHours,
          hoursSource,
          shiftsCount: data.shiftsCount,
        });
      }

      // Ordenar por gasto descendente
      result.sort((a, b) => b.totalAmount - a.totalAmount);
      return result;
    } catch (err) {
      logError('financialBI.getSpendByWorker', err);
      return [];
    }
  },

  // -------------------------------------------------------------------------
  // BI-3: Ratio custo/hora + custo-%-faturamento
  // -------------------------------------------------------------------------

  /**
   * Computa o ratio de custo (BI-3).
   * costPerHour = totalCost / totalHours (null se horas = 0).
   * costPercentRevenue = totalCost / faturamento declarado (null se não informado → exibir CTA).
   *
   * @param spendByWorker Resultado de getSpendByWorker (evita recompute).
   * @param totalCost     Gasto total (de getAccumulatedSpend).
   * @param companyId     Para buscar faturamento declarado.
   * @param yearMonth     Mês do período (Date ou YYYY-MM-DD).
   */
  async getCostRatio(
    spendByWorker: SpendByWorker[],
    totalCost: number,
    companyId: string,
    yearMonth: Date | string,
  ): Promise<CostRatio> {
    try {
      const totalHours = spendByWorker.reduce((acc, w) => acc + w.totalHours, 0);
      const costPerHour = totalHours > 0 ? totalCost / totalHours : null;

      // Normalizar year_month para o dia 1
      const ym =
        typeof yearMonth === 'string'
          ? yearMonth.slice(0, 7) + '-01'
          : `${yearMonth.getFullYear()}-${String(yearMonth.getMonth() + 1).padStart(2, '0')}-01`;

      const { data: revRow, error: revErr } = await supabase
        .from('company_monthly_revenue')
        .select('amount')
        .eq('company_id', companyId)
        .eq('year_month', ym)
        .maybeSingle();

      if (revErr) {
        logError('financialBI.getCostRatio.revenue', revErr);
      }

      const declaredRevenue =
        revRow != null ? Number((revRow as { amount: number }).amount) : null;
      const costPercentRevenue =
        declaredRevenue != null && declaredRevenue > 0
          ? (totalCost / declaredRevenue) * 100
          : null;

      return { costPerHour, totalCost, totalHours, costPercentRevenue, declaredRevenue };
    } catch (err) {
      logError('financialBI.getCostRatio', err);
      return {
        costPerHour: null,
        totalCost,
        totalHours: 0,
        costPercentRevenue: null,
        declaredRevenue: null,
      };
    }
  },

  // -------------------------------------------------------------------------
  // BI-4: Custo de no-show (heurística v1)
  // -------------------------------------------------------------------------

  /**
   * Estima o custo de no-show no período (BI-4 — HEURÍSTICA V1, ROTULADO COMO ESTIMATIVA).
   *
   * Heurística: application com invitation_response='accepted' (ou status='hired') cujo
   * turno já passou (jobs.start_date < now) E sem worker_checkout_at E sem conclusão.
   *
   * No postpago, o no-show antes da captura resulta em hold liberado (custo real = 0).
   * O estimatedAmount expõe o custo de oportunidade (valor do turno que não aconteceu).
   *
   * GAP sinalizado: sem coluna explícita no_show na v1. Se o piloto exigir precisão,
   * escalar para architect → marcador explícito de no-show em applications (migration menor).
   */
  async getNoShowCost(companyId: string, period: BIPeriod): Promise<NoShowCost> {
    const empty: NoShowCost = { estimatedCount: 0, estimatedAmount: 0, isEstimate: true };

    try {
      // Buscar jobs da empresa no período
      const { data: jobs, error: jobsErr } = await supabase
        .from('jobs')
        .select('id, start_date, budget')
        .eq('company_id', companyId)
        .gte('start_date', period.start)
        .lt('start_date', period.end);

      if (jobsErr) {
        logError('financialBI.getNoShowCost.jobs', jobsErr);
        return empty;
      }

      if (!jobs || jobs.length === 0) return empty;

      const now = new Date();
      const pastJobIds = (jobs as Array<{ id: string; start_date: string; budget: number }>)
        .filter((j) => new Date(j.start_date) < now)
        .map((j) => j.id);

      if (pastJobIds.length === 0) return empty;

      const jobBudgetMap = new Map<string, number>(
        (jobs as Array<{ id: string; budget: number }>).map((j) => [j.id, Number(j.budget ?? 0)]),
      );

      // Buscar applications de turnos passados da empresa que podem ser no-show
      const { data: apps, error: appsErr } = await supabase
        .from('applications')
        .select('id, job_id, status, worker_checkout_at, invitation_response')
        .in('job_id', pastJobIds)
        .in('status', ['hired', 'in_progress'])
        .is('worker_checkout_at', null);

      if (appsErr) {
        logError('financialBI.getNoShowCost.apps', appsErr);
        return empty;
      }

      // Filtrar: convite aceito (invitation_response='accepted' ou status='hired') sem checkout
      const noShows = ((apps ?? []) as Pick<
        ApplicationRow,
        'id' | 'job_id' | 'status' | 'worker_checkout_at' | 'invitation_response'
      >[]).filter(
        (a) =>
          a.invitation_response === 'accepted' ||
          a.status === 'hired' ||
          a.status === 'in_progress',
      );

      let estimatedAmount = 0;
      for (const ns of noShows) {
        estimatedAmount += jobBudgetMap.get(ns.job_id) ?? 0;
      }

      return {
        estimatedCount: noShows.length,
        estimatedAmount,
        isEstimate: true,
      };
    } catch (err) {
      logError('financialBI.getNoShowCost', err);
      return empty;
    }
  },

  // -------------------------------------------------------------------------
  // BI-5: Flag de concentração de horas/dias por freela (risco de vínculo)
  // -------------------------------------------------------------------------

  /**
   * Identifica freelas com horas/dias concentrados no período (BI-5).
   * Flag quando AMBOS os limiares (CONCENTRATION_HOURS_THRESHOLD e CONCENTRATION_DAYS_THRESHOLD)
   * são cruzados por um freela.
   *
   * Horas: reutiliza getSpendByWorker (se fornecido) ou recomputa.
   * Dias distintos: COUNT(DISTINCT date(jobs.start_date)) em turnos concluídos da empresa.
   *
   * Limiares (constantes de produto no topo do arquivo, não no banco):
   *  CONCENTRATION_HOURS_THRESHOLD = 150h
   *  CONCENTRATION_DAYS_THRESHOLD  = 20 dias
   */
  async getConcentrationFlags(
    companyId: string,
    period: BIPeriod,
    spendByWorker?: SpendByWorker[],
  ): Promise<ConcentrationFlag[]> {
    try {
      // Usar spendByWorker fornecido ou computar
      const workerSpend = spendByWorker ?? (await FinancialBIService.getSpendByWorker(companyId, period));

      if (workerSpend.length === 0) return [];

      const workerIds = workerSpend.map((w) => w.workerId);

      // Buscar applications concluídas da empresa para os workers no período
      // (aplicações com status 'completed' ou 'in_progress' com checkout)
      const { data: jobs, error: jobsErr } = await supabase
        .from('jobs')
        .select('id, start_date')
        .eq('company_id', companyId)
        .gte('start_date', period.start)
        .lt('start_date', period.end);

      if (jobsErr) {
        logError('financialBI.getConcentrationFlags.jobs', jobsErr);
        return [];
      }

      if (!jobs || jobs.length === 0) return [];

      const jobIds = (jobs as Array<{ id: string; start_date: string }>).map((j) => j.id);
      const jobDateMap = new Map<string, string>(
        (jobs as Array<{ id: string; start_date: string }>).map((j) => [j.id, j.start_date]),
      );

      const { data: apps, error: appsErr } = await supabase
        .from('applications')
        .select('worker_id, job_id, status')
        .in('job_id', jobIds)
        .in('worker_id', workerIds)
        .in('status', ['completed', 'in_progress', 'hired']);

      if (appsErr) {
        logError('financialBI.getConcentrationFlags.apps', appsErr);
        return [];
      }

      // Agregar dias distintos por worker
      const daysMap = new Map<string, Set<string>>();
      for (const app of (apps ?? []) as Array<{ worker_id: string; job_id: string; status: string }>) {
        const startDate = jobDateMap.get(app.job_id);
        if (!startDate) continue;
        const dayStr = startDate.slice(0, 10); // YYYY-MM-DD
        if (!daysMap.has(app.worker_id)) daysMap.set(app.worker_id, new Set());
        daysMap.get(app.worker_id)!.add(dayStr);
      }

      // Montar flags
      const flags: ConcentrationFlag[] = [];
      for (const ws of workerSpend) {
        const distinctDays = daysMap.get(ws.workerId)?.size ?? 0;
        const flagged =
          ws.totalHours >= CONCENTRATION_HOURS_THRESHOLD &&
          distinctDays >= CONCENTRATION_DAYS_THRESHOLD;

        flags.push({
          workerId: ws.workerId,
          workerName: ws.workerName,
          totalHours: ws.totalHours,
          distinctDays,
          flagged,
          hoursThreshold: CONCENTRATION_HOURS_THRESHOLD,
          daysThreshold: CONCENTRATION_DAYS_THRESHOLD,
        });
      }

      // Flagged primeiro, depois ordenado por horas descendente
      flags.sort((a, b) => {
        if (a.flagged !== b.flagged) return a.flagged ? -1 : 1;
        return b.totalHours - a.totalHours;
      });

      return flags;
    } catch (err) {
      logError('financialBI.getConcentrationFlags', err);
      return [];
    }
  },

  // -------------------------------------------------------------------------
  // Conveniência: todos os BI de uma vez (para o hook useFinancialBI)
  // -------------------------------------------------------------------------

  /**
   * Computa todos os indicadores do período de uma vez.
   * Reutiliza getSpendByWorker entre BI-2, BI-3 e BI-5 para evitar queries duplas.
   *
   * @param companyId UUID da empresa.
   * @param period    Período (usar currentMonthPeriod() ou customPeriod()).
   */
  async getAllBI(
    companyId: string,
    period: BIPeriod,
  ): Promise<{
    accumulatedSpend: AccumulatedSpend;
    spendByWorker: SpendByWorker[];
    costRatio: CostRatio;
    noShowCost: NoShowCost;
    concentrationFlags: ConcentrationFlag[];
  }> {
    // Computar em paralelo onde não há dependência
    const [accumulatedSpend, spendByWorker, noShowCost] = await Promise.all([
      FinancialBIService.getAccumulatedSpend(companyId, period),
      FinancialBIService.getSpendByWorker(companyId, period),
      FinancialBIService.getNoShowCost(companyId, period),
    ]);

    // BI-3 e BI-5 dependem de spendByWorker
    const [costRatio, concentrationFlags] = await Promise.all([
      FinancialBIService.getCostRatio(
        spendByWorker,
        accumulatedSpend.totalAmount,
        companyId,
        period.start,
      ),
      FinancialBIService.getConcentrationFlags(companyId, period, spendByWorker),
    ]);

    return { accumulatedSpend, spendByWorker, costRatio, noShowCost, concentrationFlags };
  },
};

/**
 * Hooks de inteligência financeira — Slice 3 (R12-R16).
 *
 * useSpendLimit: CRUD do teto de gasto mensal da empresa + faturamento declarado.
 * useFinancialBI: todos os indicadores BI do período (BI-1 a BI-5) + avaliação de alerta on-demand.
 *
 * Padrões do projeto:
 *  - useState + useEffect + supabase.from direto (Art. 5 — sem React Query).
 *  - Tipos à mão em types/index.ts (Art. 2).
 *  - Imports relativos (sem alias @/).
 *  - logError (nunca console.log).
 */

import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../lib/supabase';
import { SpendLimitService } from '../services/spendLimitService';
import { FinancialBIService, currentMonthPeriod, type BIPeriod } from '../services/financialBIService';
import { logError } from '../lib/logger';
import type {
  SpendLimit,
  MonthlyRevenue,
  FinancialBIData,
} from '../types';

// ---------------------------------------------------------------------------
// useSpendLimit — CRUD do teto + faturamento
// ---------------------------------------------------------------------------

export interface UseSpendLimitResult {
  /** Teto configurado (null = não configurado). */
  spendLimit: SpendLimit | null;
  /** Faturamento declarado do mês de referência (null = não informado). */
  monthlyRevenue: MonthlyRevenue | null;
  loading: boolean;
  error: string | null;
  /**
   * Cria ou atualiza o teto de gasto mensal.
   * @returns true em caso de sucesso.
   */
  upsertSpendLimit: (params: {
    amount: number;
    alertThresholds?: number[];
    financialContactEmail?: string | null;
    financialContactPhone?: string | null;
  }) => Promise<boolean>;
  /**
   * Cria ou atualiza o faturamento declarado do mês.
   * @returns true em caso de sucesso.
   */
  upsertMonthlyRevenue: (amount: number, yearMonth?: Date | string) => Promise<boolean>;
  /** Recarregar dados. */
  refresh: () => void;
}

/**
 * Hook para EMPRESA — gerenciar teto de gasto e faturamento declarado.
 *
 * @param yearMonth Mês de referência para o faturamento (default: mês corrente).
 */
export function useSpendLimit(yearMonth?: Date | string): UseSpendLimitResult {
  const [spendLimit, setSpendLimit] = useState<SpendLimit | null>(null);
  const [monthlyRevenue, setMonthlyRevenue] = useState<MonthlyRevenue | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [companyId, setCompanyId] = useState<string | null>(null);
  const navigate = useNavigate();

  // Mês de referência estável
  const refMonth: Date | string = yearMonth ?? new Date();

  const load = useCallback(
    async (cid?: string) => {
      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) {
          navigate('/login');
          return;
        }

        setLoading(true);
        setError(null);

        let resolvedCompanyId = cid ?? companyId;
        if (!resolvedCompanyId) {
          const { data: company, error: cErr } = await supabase
            .from('companies')
            .select('id')
            .eq('owner_id', user.id)
            .maybeSingle();
          if (cErr) {
            logError('useSpendLimit.load.company', cErr);
            setError('Erro ao carregar dados da empresa.');
            setLoading(false);
            return;
          }
          if (!company) {
            setLoading(false);
            return;
          }
          resolvedCompanyId = company.id as string;
          setCompanyId(resolvedCompanyId);
        }

        const [limit, revenue] = await Promise.all([
          SpendLimitService.getSpendLimit(resolvedCompanyId, null),
          SpendLimitService.getMonthlyRevenue(resolvedCompanyId, refMonth),
        ]);

        setSpendLimit(limit);
        setMonthlyRevenue(revenue);
      } catch (err) {
        logError('useSpendLimit.load', err);
        setError('Erro ao carregar dados financeiros.');
      } finally {
        setLoading(false);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [navigate, companyId],
  );

  useEffect(() => {
    let active = true;
    void (async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        navigate('/login');
        return;
      }

      setLoading(true);
      setError(null);

      const { data: company, error: cErr } = await supabase
        .from('companies')
        .select('id')
        .eq('owner_id', user.id)
        .maybeSingle();

      if (cErr || !company) {
        if (active) {
          setLoading(false);
          if (cErr) setError('Erro ao carregar dados da empresa.');
        }
        return;
      }

      const cid = company.id as string;
      if (active) setCompanyId(cid);

      const [limit, revenue] = await Promise.all([
        SpendLimitService.getSpendLimit(cid, null),
        SpendLimitService.getMonthlyRevenue(cid, refMonth),
      ]);

      if (!active) return;
      setSpendLimit(limit);
      setMonthlyRevenue(revenue);
      setLoading(false);
    })();
    return () => {
      active = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [navigate]);

  const upsertSpendLimit = useCallback(
    async (params: {
      amount: number;
      alertThresholds?: number[];
      financialContactEmail?: string | null;
      financialContactPhone?: string | null;
    }): Promise<boolean> => {
      if (!companyId) return false;
      const result = await SpendLimitService.upsertSpendLimit(companyId, params);
      if (!result) return false;
      setSpendLimit(result);
      return true;
    },
    [companyId],
  );

  const upsertMonthlyRevenue = useCallback(
    async (amount: number, ym?: Date | string): Promise<boolean> => {
      if (!companyId) return false;
      const result = await SpendLimitService.upsertMonthlyRevenue(
        companyId,
        ym ?? refMonth,
        amount,
      );
      if (!result) return false;
      setMonthlyRevenue(result);
      return true;
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [companyId],
  );

  return {
    spendLimit,
    monthlyRevenue,
    loading,
    error,
    upsertSpendLimit,
    upsertMonthlyRevenue,
    refresh: () => void load(),
  };
}

// ---------------------------------------------------------------------------
// useFinancialBI — todos os indicadores do período
// ---------------------------------------------------------------------------

export interface UseFinancialBIResult {
  data: FinancialBIData | null;
  loading: boolean;
  error: string | null;
  /** company_id resolvido (necessário para ações da UI). */
  companyId: string;
  /** Recarregar dados + disparar avaliação de alerta on-demand. */
  refresh: () => void;
}

/**
 * Hook para EMPRESA — carregar todos os indicadores BI do período.
 * Avalia o alerta de teto on-demand ao carregar (best-effort, não bloqueia).
 *
 * @param period Período de análise. Default: mês corrente.
 */
export function useFinancialBI(period?: BIPeriod): UseFinancialBIResult {
  const [data, setData] = useState<FinancialBIData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [companyId, setCompanyId] = useState<string>('');
  const navigate = useNavigate();

  const resolvedPeriod: BIPeriod = period ?? currentMonthPeriod();

  const load = useCallback(
    async (cid?: string) => {
      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (!user) {
          navigate('/login');
          return;
        }

        setLoading(true);
        setError(null);

        let resolvedCompanyId = cid ?? companyId;
        if (!resolvedCompanyId) {
          const { data: company, error: cErr } = await supabase
            .from('companies')
            .select('id')
            .eq('owner_id', user.id)
            .maybeSingle();
          if (cErr || !company) {
            setError('Empresa não encontrada.');
            setLoading(false);
            return;
          }
          resolvedCompanyId = company.id as string;
          setCompanyId(resolvedCompanyId);
        }

        const biData = await FinancialBIService.getAllBI(resolvedCompanyId, resolvedPeriod);
        setData(biData);

        // Avaliar alerta de teto on-demand (best-effort — não bloqueia UI)
        void SpendLimitService.evaluateSpendAlert(resolvedCompanyId).catch((alertErr) => {
          logError('useFinancialBI.evaluateSpendAlert', alertErr);
        });
      } catch (err) {
        logError('useFinancialBI.load', err);
        setError('Erro ao carregar indicadores financeiros.');
      } finally {
        setLoading(false);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [navigate, companyId, resolvedPeriod.start, resolvedPeriod.end],
  );

  useEffect(() => {
    let active = true;
    void (async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        navigate('/login');
        return;
      }

      setLoading(true);
      setError(null);

      const { data: company, error: cErr } = await supabase
        .from('companies')
        .select('id')
        .eq('owner_id', user.id)
        .maybeSingle();

      if (cErr || !company) {
        if (active) {
          setError('Empresa não encontrada.');
          setLoading(false);
        }
        return;
      }

      const cid = company.id as string;
      if (active) setCompanyId(cid);

      const biData = await FinancialBIService.getAllBI(cid, resolvedPeriod);
      if (!active) return;

      setData(biData);
      setLoading(false);

      // Avaliar alerta de teto on-demand (best-effort)
      void SpendLimitService.evaluateSpendAlert(cid).catch((alertErr) => {
        logError('useFinancialBI.evaluateSpendAlert', alertErr);
      });
    })();
    return () => {
      active = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [navigate, resolvedPeriod.start, resolvedPeriod.end]);

  return {
    data,
    loading,
    error,
    companyId,
    refresh: () => void load(),
  };
}

